DROP TRIGGER kids_history_message_identity;
--> statement-breakpoint
CREATE TRIGGER kids_history_message_identity BEFORE INSERT ON kids_hosted_history_messages
WHEN NEW.raw_body IS NULL OR NEW.consumed_at IS NOT NULL OR length(CAST(NEW.raw_body AS BLOB))<>NEW.raw_bytes OR length(NEW.body_hash)<>64 OR length(NEW.fingerprint)<>64
 OR NOT EXISTS(SELECT 1 FROM kids_hosted_history_pages p JOIN kids_hosted_history_scans s ON s.id=p.scan_id WHERE p.id=NEW.page_id AND p.status='fetching' AND p.response_hash IS NOT NULL AND p.lease_token IS NOT NULL AND p.lease_until>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND s.binding_id=NEW.binding_id AND s.chat_id=NEW.chat_id AND json_extract(s.authority_json,'$.bindingRevision')=NEW.binding_revision AND json_extract(s.authority_json,'$.epoch')=NEW.epoch AND json_extract(NEW.raw_body,'$.id')=NEW.message_id AND json_extract(NEW.raw_body,'$.chat_id')=NEW.chat_id)
 OR EXISTS(SELECT 1 FROM kids_hosted_events w WHERE w.binding_id=NEW.binding_id AND w.chat_id=NEW.chat_id AND w.message_id=NEW.message_id)
 OR EXISTS(SELECT 1 FROM kids_hosted_message_heads w WHERE w.binding_id=NEW.binding_id AND w.chat_id=NEW.chat_id AND w.message_id=NEW.message_id)
 OR (NOT EXISTS(SELECT 1 FROM kids_hosted_history_pages p JOIN kids_hosted_history_scans s ON s.id=p.scan_id WHERE p.id=NEW.page_id AND json_extract(s.authority_json,'$.endpointId') LIKE 'poll:%') AND EXISTS(SELECT 1 FROM kids_hosted_history_heads w WHERE w.binding_id=NEW.binding_id AND w.chat_id=NEW.chat_id AND w.message_id=NEW.message_id))
 OR EXISTS(SELECT 1 FROM kids_hosted_history_messages w WHERE w.binding_id=NEW.binding_id AND w.chat_id=NEW.chat_id AND w.message_id=NEW.message_id AND w.consumed_at IS NULL)
 OR EXISTS(SELECT 1 FROM kids_hosted_history_messages w JOIN kids_hosted_history_pages p ON p.id=w.page_id JOIN kids_hosted_history_pages n ON n.scan_id=p.scan_id WHERE n.id=NEW.page_id AND w.binding_id=NEW.binding_id AND w.chat_id=NEW.chat_id AND w.message_id=NEW.message_id AND w.fingerprint<>NEW.fingerprint)
BEGIN SELECT RAISE(ABORT,'KIDS_HISTORY_MESSAGE_IDENTITY'); END;
--> statement-breakpoint
DROP TRIGGER kids_history_head_identity;
--> statement-breakpoint
CREATE TRIGGER kids_history_head_identity BEFORE INSERT ON kids_hosted_history_heads
WHEN NOT EXISTS(SELECT 1 FROM kids_hosted_history_messages m JOIN kids_hosted_history_batch_members x ON x.message_sequence=m.sequence JOIN kids_hosted_batches b ON b.id=x.batch_id JOIN kids_operation_receipts r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id AND r.operation_id=b.operation_id WHERE m.sequence=NEW.message_sequence AND m.binding_id=NEW.binding_id AND m.chat_id=NEW.chat_id AND m.message_id=NEW.message_id AND m.body_hash=NEW.body_hash AND m.fingerprint=NEW.fingerprint AND m.raw_body IS NOT NULL AND m.consumed_at IS NULL AND b.status='saved' AND b.source_kind='history' AND ((x.prior_head_sequence IS NULL AND x.prior_head_hash IS NULL AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=NEW.binding_id AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id)) OR EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=NEW.binding_id AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id AND h.message_sequence=x.prior_head_sequence AND h.body_hash=x.prior_head_hash)) AND r.body_hash=b.submitted_hash AND r.committed_revision=b.committed_revision AND json_extract(r.source_authority,'$.batchId')=b.id AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_messages n WHERE n.binding_id=m.binding_id AND n.chat_id=m.chat_id AND n.message_id=m.message_id AND n.sequence>m.sequence) AND NOT EXISTS(SELECT 1 FROM kids_hosted_events w WHERE w.binding_id=m.binding_id AND w.chat_id=m.chat_id AND w.message_id=m.message_id) AND NOT EXISTS(SELECT 1 FROM kids_hosted_message_heads w WHERE w.binding_id=m.binding_id AND w.chat_id=m.chat_id AND w.message_id=m.message_id))
BEGIN SELECT RAISE(ABORT,'KIDS_HISTORY_HEAD_IDENTITY'); END;
--> statement-breakpoint
DROP TRIGGER kids_history_head_immutable;
--> statement-breakpoint
CREATE TRIGGER kids_history_head_immutable BEFORE UPDATE ON kids_hosted_history_heads
WHEN NEW.binding_id IS NOT OLD.binding_id OR NEW.chat_id IS NOT OLD.chat_id OR NEW.message_id IS NOT OLD.message_id OR NEW.message_sequence<=OLD.message_sequence OR NOT EXISTS(SELECT 1 FROM kids_hosted_history_messages m JOIN kids_hosted_history_batch_members x ON x.message_sequence=m.sequence JOIN kids_hosted_batches b ON b.id=x.batch_id JOIN kids_operation_receipts r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id AND r.operation_id=b.operation_id WHERE m.sequence=NEW.message_sequence AND m.binding_id=NEW.binding_id AND m.chat_id=NEW.chat_id AND m.message_id=NEW.message_id AND m.body_hash=NEW.body_hash AND m.fingerprint=NEW.fingerprint AND m.raw_body IS NOT NULL AND m.consumed_at IS NULL AND b.status='saved' AND b.source_kind='history' AND ((x.prior_head_sequence IS NULL AND x.prior_head_hash IS NULL AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=NEW.binding_id AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id)) OR EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=NEW.binding_id AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id AND h.message_sequence=x.prior_head_sequence AND h.body_hash=x.prior_head_hash)) AND r.body_hash=b.submitted_hash AND r.committed_revision=b.committed_revision AND json_extract(r.source_authority,'$.batchId')=b.id AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_messages n WHERE n.binding_id=m.binding_id AND n.chat_id=m.chat_id AND n.message_id=m.message_id AND n.sequence>m.sequence) AND NOT EXISTS(SELECT 1 FROM kids_hosted_events w WHERE w.binding_id=m.binding_id AND w.chat_id=m.chat_id AND w.message_id=m.message_id) AND NOT EXISTS(SELECT 1 FROM kids_hosted_message_heads w WHERE w.binding_id=m.binding_id AND w.chat_id=m.chat_id AND w.message_id=m.message_id))
BEGIN SELECT RAISE(ABORT,'KIDS_HISTORY_HEAD_IMMUTABLE'); END;

