DROP TRIGGER kids_history_member_identity;
--> statement-breakpoint
CREATE TRIGGER kids_history_member_identity BEFORE INSERT ON kids_hosted_history_batch_members
WHEN (NEW.prior_head_sequence IS NULL)<>(NEW.prior_head_hash IS NULL) OR (NEW.prior_head_sequence IS NOT NULL AND (NEW.prior_head_sequence<1 OR NEW.prior_head_sequence>=NEW.message_sequence OR length(NEW.prior_head_hash)<>64)) OR NOT ((NEW.prior_head_sequence IS NULL AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=(SELECT binding_id FROM kids_hosted_batches WHERE id=NEW.batch_id) AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id)) OR EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=(SELECT binding_id FROM kids_hosted_batches WHERE id=NEW.batch_id) AND h.chat_id=NEW.chat_id AND h.message_id=NEW.message_id AND h.message_sequence=NEW.prior_head_sequence AND h.body_hash=NEW.prior_head_hash)) OR (SELECT COUNT(*) FROM kids_hosted_history_batch_members WHERE batch_id=NEW.batch_id)>=10 OR NOT EXISTS(SELECT 1 FROM kids_hosted_batches b JOIN kids_hosted_history_messages m ON m.sequence=NEW.message_sequence JOIN kids_hosted_history_pages p ON p.id=m.page_id WHERE b.id=NEW.batch_id AND b.source_kind='history' AND b.status='ready' AND p.status='committed' AND p.response_hash IS NOT NULL AND p.owner_user_id=b.owner_user_id AND p.workspace_id=b.workspace_id AND m.binding_id=b.binding_id AND m.binding_revision=b.binding_revision AND m.epoch=b.epoch AND m.chat_id=b.chat_id AND m.chat_id=NEW.chat_id AND m.message_id=NEW.message_id AND m.body_hash=NEW.body_hash AND m.fingerprint=NEW.fingerprint AND m.raw_body IS NOT NULL AND m.consumed_at IS NULL)
BEGIN SELECT RAISE(ABORT,'KIDS_HISTORY_MEMBER_IDENTITY'); END;
